// WHOSE PROJECTS? The portal supplies this, having derived it from a
// session it verified (HMAC over username|expiry, expiry capped by the
// Dex token). Nothing here re-derives identity; this workflow's job is
// to answer for exactly the user it was asked about, and nobody else.
//
// THE EMPTY CASE IS LOAD-BEARING. A blank username would build the
// selector `owner=` - and a namespace list WITHOUT a working selector
// returns EVERY tenant's namespace (measured: 23 of them). So a missing
// username is refused outright rather than allowed to widen the query.
const raw = $input.first().json || {};
const body = raw.body || raw;
const username = String(body.username || '').trim().toLowerCase();

// Same shape FreeIPA usernames are validated to on the way in.
const usable = /^[a-z][a-z0-9._-]{2,31}$/.test(username);

return [{ json: { username, usable,
  // Pre-encoded so the selector cannot be broken by an unexpected
  // character further down.
  sel: encodeURIComponent(username) } }];

// Merge the two selector results and answer. New namespaces carry BOTH
// `owner` and `tenant` with the same value, so the two queries overlap -
// dedupe by namespace name. Legacy ones match only the second.
//
// Nothing here decides ownership: every item arrived because the API
// server matched it against a selector bound to this user. This code
// only shapes the answer.
const who = $('Whose projects?').first().json;

function items(nodeName) {
  try {
    const j = $(nodeName).first().json;
    return (j && Array.isArray(j.items)) ? j.items : [];
  } catch (e) { return []; }
}

const byName = {};
for (const ns of items('Projects they own').concat(items('Their legacy projects'))) {
  const m = ns.metadata || {};
  if (!m.name) continue;
  const labels = m.labels || {};
  byName[m.name] = {
    namespace: m.name,
    // Legacy namespaces have no `project` label; their name minus the
    // prefix is the closest honest answer.
    project: labels.project || m.name.replace(/^tenant-/, ''),
    url: 'http://' + m.name + '.apps.cloudlab.internal/',
    created: m.creationTimestamp || null,
    legacy: !labels.owner
  };
}

const projects = Object.keys(byName).sort().map(k => byName[k]);

// ONE ITEM PER PROJECT from here on, so the next node can ask about each
// one individually. A stop-routing delete leaves the namespace in place
// (that is the whole scope of a delete), so a namespace existing no
// longer means the project is reachable - the Ingress is what decides
// that, and it has to be looked up per project.
//
// THE EMPTY CASE IS NOT AN EMPTY OUTPUT. n8n does not run a node with no
// input, so returning [] here would kill the branch and the responder
// would never fire - the portal would hang and then show a generic 503
// while the execution reported success (Problem #135). A user with no
// projects is a normal answer, so it travels as one explicit item.
if (!projects.length) {
  return [{ json: { username: who.username, empty: true } }];
}
return projects.map(p => ({ json: Object.assign({ username: who.username }, p) }));

// A username we will not query for. Answering with an empty list is the
// honest result: we are not saying they have no projects, we are saying
// we were not asked a question we can answer safely.
return [{ json: { username: '', count: 0, projects: [], refused: true } }];

// PAIR each project with its own Ingress lookup.
//
// The HTTP node ran once per input item, so its outputs line up with the
// projects by index. That assumption is CHECKED rather than trusted: if
// the counts ever disagree, every project is reported as routing=null
// instead of being paired up wrongly. Mislabelling a live project as
// stopped is worse than admitting we do not know.
const projects = $('Merge and answer').all().map(i => i.json);
const items = $input.all();
const looks = items.map(i => i.json);
const aligned = projects.length === looks.length;

// PREFER n8n's own pairing over positional order. Each item carries
// pairedItem pointing back at the input index that produced it; using it
// means a reorder cannot silently attach one project's answer to another
// project's card. Index order is the fallback, and it is only trusted
// when the counts match.
//
// Why this matters more than it looks: a mispairing does not error, it
// renders "Arrete" on a project that is running perfectly well. That is
// a false status claim, which is the thing #136 exists to prevent.
const byPair = {};
items.forEach((it, idx) => {
  let p = it.pairedItem;
  if (p && typeof p === 'object') p = Array.isArray(p) ? p[0] : p;
  const src = (p && typeof p === 'object' && typeof p.item === 'number')
    ? p.item : (typeof p === 'number' ? p : idx);
  if (byPair[src] === undefined) byPair[src] = idx;
});

function routingOf(i) {
  if (!aligned) return null;
  const at = byPair[i] !== undefined ? byPair[i] : i;
  const r = looks[at];
  if (!r) return null;
  const code = r.statusCode || 0;
  if (code === 200) return true;    // the Ingress exists: the host is claimed
  if (code === 404) return false;   // no Ingress: nothing routes to this name
  return null;                      // 403, timeout, anything else: unknown
}

const out = projects.map((p, i) => {
  const routing = routingOf(i);
  return {
    namespace: p.namespace,
    project: p.project,
    created: p.created,
    legacy: p.legacy,
    routing: routing,
    // THE URL IS ONLY SENT WHEN SOMETHING ANSWERS AT IT. A project whose
    // Ingress is gone has no browsable address, and handing the portal a
    // link that is known to 404 is worse than handing it none - the same
    // rule the provisioner follows for siteUrl.
    url: routing === false ? null
       : 'http://' + p.namespace + '.apps.cloudlab.internal/'
  };
});

return [{ json: { username: projects[0].username, count: out.length,
  projects: out } }];

// No projects. A real, complete answer - not a failure, and not the
// same thing as the refusal path, which means we would not ask.
const who = $('Whose projects?').first().json;
return [{ json: { username: who.username, count: 0, projects: [] } }];
